template<>struct Wire<PC_ADAPTER> {static Json Encode(const PC_ADAPTER& v){Json j=Json::object();j["id"]=EncodeWire(v.id);j["luid"]=EncodeWire(v.luid);j["ifindex"]=EncodeWire(v.ifindex);j["running"]=EncodeWire(v.running);j["mac"]=EncodeWire(v.mac);j["reserved"]=EncodeWire(v.reserved);j["name"]=EncodeWire(v.name);return j;}static void Decode(const Json& j,PC_ADAPTER& v){Require(j.is_object(),"Wire struct must be object");for(auto it=j.begin();it!=j.end();++it){if(it.key()=="id")DecodeWire(it.value(),v.id);else if(it.key()=="luid")DecodeWire(it.value(),v.luid);else if(it.key()=="ifindex")DecodeWire(it.value(),v.ifindex);else if(it.key()=="running")DecodeWire(it.value(),v.running);else if(it.key()=="mac")DecodeWire(it.value(),v.mac);else if(it.key()=="reserved")DecodeWire(it.value(),v.reserved);else if(it.key()=="name")DecodeWire(it.value(),v.name);else throw SdkError(87,"Unknown wire field: "+it.key());}}};
